// =============================================================================
// html-cache.ts — runtime reader for the build-time HTML cache.
//
// Reads the pre-rendered HTML from .cache/content/ (generated by the
// build-html-cache.ts script).  All functions are read-only; they never
// touch markdown files or the unified pipeline.
//
// On cache miss (no index file, missing HTML, etc.) every function returns
// null — callers MUST fall back to the existing MarkdownAsync / renderChapter
// path.  This guarantees the old flow still works during development or when
// the cache hasn't been built yet.
// =============================================================================

import { readFile } from '../fs/fs'
import type { ContentType, Locale, TocItem, Frontmatter } from '@/types'

// ---------------------------------------------------------------------------
// Cache-specific types
// ---------------------------------------------------------------------------

export interface CachedChapterEntry {
  slug: string
  title: string
  chapter: number
  /** Path relative to .cache/content/, e.g. "notes/software-exam/ch1.html" */
  htmlPath: string
  toc: TocItem[]
}

export interface CachedBookEntry {
  slug: string
  title: string
  chapters: CachedChapterEntry[]
}

export interface CachedStandaloneEntry {
  slug: string
  lang: string
  /** Path relative to .cache/content/, e.g. "articles/markdown-usage-guide.html" */
  htmlPath: string
  frontmatter: Frontmatter
  toc: TocItem[]
}

// ---------------------------------------------------------------------------
// Internal index type (matches what build-html-cache.ts writes)
// ---------------------------------------------------------------------------

interface RawCacheIndex {
  version: number
  generatedAt: string
  standalone: Record<string, RawStandalone[]>
  books: Record<string, RawBook[]>
}

interface RawStandalone {
  slug: string
  lang: string
  htmlPath: string
  frontmatter: Frontmatter
  toc: TocItem[]
}

interface RawBook {
  slug: string
  title: string
  chapters: RawChapter[]
}

interface RawChapter {
  slug: string
  title: string
  chapter: number
  htmlPath: string
  toc: TocItem[]
}

// ---------------------------------------------------------------------------
// Lazy-load the cache index (singleton, in-memory)
// ---------------------------------------------------------------------------

let _indexPromise: Promise<RawCacheIndex | null> | null = null

function loadIndex(): Promise<RawCacheIndex | null> {
  if (_indexPromise) return _indexPromise

  _indexPromise = (async () => {
    try {
      const raw = await readFile('.cache/content/index.json')
      return JSON.parse(raw) as RawCacheIndex
    } catch {
      // No cache yet — caller must fall back to runtime rendering
      return null
    }
  })()

  return _indexPromise
}

// ---------------------------------------------------------------------------
// Clear the in-memory index (useful during development when rebuilding)
// ---------------------------------------------------------------------------

export function clearCacheIndex(): void {
  _indexPromise = null
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Reads a single cached HTML file.
 *
 * @param htmlPath — path relative to .cache/content/ (from the index)
 * @returns The rendered HTML string, or null on cache miss.
 */
export async function getCachedHtml(htmlPath: string): Promise<string | null> {
  try {
    return await readFile(`.cache/content/${htmlPath}`)
  } catch {
    return null
  }
}

/**
 * Looks up a book in the cache index.
 *
 * @param type — content type (e.g. "study-notes")
 * @param slug — book slug (e.g. "software-exam")
 */
export async function getCachedBook(
  type: ContentType,
  slug: string,
): Promise<CachedBookEntry | null> {
  const index = await loadIndex()
  if (!index) return null

  const books = index.books[type]
  if (!books) return null

  const book = books.find((b) => b.slug === slug)
  if (!book) return null

  return {
    slug: book.slug,
    title: book.title,
    chapters: book.chapters.map((ch) => ({
      slug: ch.slug,
      title: ch.title,
      chapter: ch.chapter,
      htmlPath: ch.htmlPath,
      toc: ch.toc,
    })),
  }
}

/**
 * Looks up a standalone article in the cache index.
 *
 * @param type — content type (e.g. "articles")
 * @param slug — article slug
 * @param lang — locale (e.g. "zh")
 */
export async function getCachedStandalone(
  type: ContentType,
  slug: string,
  lang: Locale,
): Promise<CachedStandaloneEntry | null> {
  const index = await loadIndex()
  if (!index) return null

  const items = index.standalone[type]
  if (!items) return null

  const item = items.find((a) => a.slug === slug && a.lang === lang)
  if (!item) return null

  return {
    slug: item.slug,
    lang: item.lang,
    htmlPath: item.htmlPath,
    frontmatter: item.frontmatter,
    toc: item.toc,
  }
}

/**
 * Builds a Map<chapterSlug, htmlPath> for fast lookup in BookPage.
 * Returns an empty map if the cache is unavailable.
 */
export async function getChapterHtmlPathMap(
  type: ContentType,
  bookSlug: string,
): Promise<Map<string, string>> {
  const map = new Map<string, string>()
  const book = await getCachedBook(type, bookSlug)
  if (!book) return map

  for (const ch of book.chapters) {
    map.set(ch.slug, ch.htmlPath)
  }

  return map
}
